// Validate the upload before spending an AI call or touching Shopify.
const MAX_BYTES = 8 * 1024 * 1024;
const OK_MIME = ['image/jpeg', 'image/png', 'image/webp'];
// Magic bytes, so a renamed .exe cannot pose as a .jpg.
const SIG = {
  'image/jpeg': [[0xFF, 0xD8, 0xFF]],
  'image/png':  [[0x89, 0x50, 0x4E, 0x47]],
  'image/webp': [[0x52, 0x49, 0x46, 0x46]],
};

const item = $input.first();
const bin = item.binary && item.binary.image;
if (!bin) throw new Error('No image uploaded. Send multipart/form-data with a field named "image".');

const buf = Buffer.from(bin.data, 'base64');
if (buf.length > MAX_BYTES) throw new Error(`Image is ${(buf.length/1048576).toFixed(1)}MB; limit is 8MB.`);

const mime = (bin.mimeType || '').toLowerCase();
if (!OK_MIME.includes(mime)) throw new Error(`Unsupported type "${mime}". Use JPEG, PNG or WebP.`);

const sigs = SIG[mime];
const head = [...buf.subarray(0, 4)];
const matches = sigs.some(s => s.every((b, i) => head[i] === b));
if (!matches) throw new Error('File contents do not match the declared image type.');

const title = (item.json.title || '').toString().trim().slice(0, 120) || 'Untitled outfit';

return [{
  json: { title, mime, bytes: buf.length, filename: bin.fileName || 'outfit.jpg' },
  binary: { image: bin },
}];

