// The model's reply is UNTRUSTED INPUT. Validate it against a strict schema
// before anything downstream touches it. Never eval, never render raw.
const res = $input.first().json;

if (res.error) {
  const m = (res.error.message || '').toString();
  const code = res.error.code;
  if (code === 401 || /auth/i.test(m)) throw new Error('OpenRouter rejected the API key. Check the credential in n8n.');
  if (code === 402 || /credit|quota/i.test(m)) throw new Error('OpenRouter quota exhausted. Top up or wait for the free tier to reset. No paid model was substituted.');
  if (code === 404) throw new Error('That model id is not available to your account. Check https://openrouter.ai/models for a vision-capable alternative.');
  throw new Error('OpenRouter error: ' + m.slice(0, 200));
}

const text = res?.choices?.[0]?.message?.content;
if (typeof text !== 'string' || !text.trim()) throw new Error('Model returned an empty response.');

// Models often wrap JSON in prose or a code fence. Extract the outermost array.
let raw = text.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const start = raw.indexOf('[');
const end = raw.lastIndexOf(']');
if (start === -1 || end === -1) throw new Error('Model did not return a JSON array. Raw start: ' + raw.slice(0, 120));

let parsed;
try { parsed = JSON.parse(raw.slice(start, end + 1)); }
catch (e) { throw new Error('Model returned malformed JSON: ' + e.message); }
if (!Array.isArray(parsed)) throw new Error('Expected a JSON array of garments.');

const CATEGORIES = ['t-shirt','shirt','hoodie','sweatshirt','jacket','coat','trousers','jeans','shorts',
  'skirt','dress','shoes','sneakers','boots','bag','hat','belt','accessory'];

const num01 = (v) => typeof v === 'number' && isFinite(v) && v >= 0 && v <= 1;

const garments = [];
const rejected = [];

parsed.slice(0, 12).forEach((g, i) => {
  const why = [];
  const cat = (g.category || '').toString().toLowerCase().trim();
  if (!CATEGORIES.includes(cat)) why.push(`unknown category "${cat}"`);

  const bb = g.bbox || {};
  if (!['x','y','w','h'].every(k => num01(bb[k]))) why.push('bbox outside 0-1');

  let ax = g.anchor?.x, ay = g.anchor?.y;
  if (!num01(ax) || !num01(ay)) {            // derive the anchor from the box centre
    ax = num01(bb.x) && num01(bb.w) ? bb.x + bb.w / 2 : null;
    ay = num01(bb.y) && num01(bb.h) ? bb.y + bb.h / 2 : null;
  }
  if (!num01(ax) || !num01(ay)) why.push('no usable anchor');

  let conf = g.confidence;
  if (typeof conf !== 'number' || !isFinite(conf) || conf < 0 || conf > 1) conf = 0;

  if (why.length) { rejected.push({ index: i, reasons: why }); return; }

  garments.push({
    id: `g${i + 1}`,
    category: cat,
    colour: (g.color || g.colour || '').toString().slice(0, 40),
    descriptors: (g.descriptors || g.style || '').toString().slice(0, 200),
    description: (g.description || '').toString().slice(0, 300),
    bbox: { x: +bb.x.toFixed(4), y: +bb.y.toFixed(4), w: +bb.w.toFixed(4), h: +bb.h.toFixed(4) },
    anchor: { x: +ax.toFixed(4), y: +ay.toFixed(4) },
    confidence: +conf.toFixed(3),
    ambiguity: (g.ambiguity || '').toString().slice(0, 200),
  });
});

if (!garments.length) throw new Error('No valid garments survived validation. Rejected: ' + JSON.stringify(rejected));

return [{ json: { garments, rejected, model: res.model || null, usage: res.usage || null } }];

