// Deterministic, explainable matching. The model NEVER supplies catalogue data;
// it only describes pixels. Products come from Shopify and nowhere else.
const garments = $('Validate AI response').first().json.garments;
const resp = $input.first().json;

if (resp.errors) throw new Error('Shopify product query failed: ' + JSON.stringify(resp.errors).slice(0, 300));

const products = (resp?.data?.products?.nodes || []).map(p => ({
  id: p.id,
  handle: p.handle,
  title: p.title,
  type: (p.productType || '').toLowerCase(),
  tags: (p.tags || []).map(t => t.toLowerCase()),
  available: !!p.variants?.nodes?.some(v => v.availableForSale),
  price: p.variants?.nodes?.[0]?.price || null,
  image: p.featuredMedia?.preview?.image?.url || null,
  haystack: [p.title, p.productType, (p.tags || []).join(' '), p.description || '']
    .join(' ').toLowerCase(),
}));

if (!products.length) throw new Error('Shopify returned no products; cannot match anything.');

// Map a detected garment category onto words that would appear in a listing.
const SYNONYMS = {
  'hoodie': ['hoodie','hooded','sweatshirt'], 'sweatshirt': ['sweatshirt','hoodie','crewneck'],
  't-shirt': ['t-shirt','tee','tshirt'], 'shirt': ['shirt','polo','button'],
  'jacket': ['jacket','outerwear','coat','bomber'], 'coat': ['coat','jacket','parka'],
  'trousers': ['trouser','pant','chino','jogger'], 'jeans': ['jean','denim'],
  'shorts': ['short'], 'skirt': ['skirt'], 'dress': ['dress'],
  'shoes': ['shoe','footwear'], 'sneakers': ['sneaker','trainer','shoe'], 'boots': ['boot'],
  'bag': ['bag','tote','backpack'], 'hat': ['hat','cap','beanie'],
  'belt': ['belt'], 'accessory': ['accessor','scarf','sock'],
};
const COLOURS = ['black','white','grey','gray','navy','blue','red','green','brown','beige','cream',
  'tan','pink','purple','yellow','orange','olive','charcoal','floral'];

const HIGH = 0.70, LOW = 0.40;

const out = garments.map(g => {
  const words = SYNONYMS[g.category] || [g.category];
  const gColour = COLOURS.find(c => (g.colour || '').toLowerCase().includes(c));

  const scored = products.map(p => {
    let score = 0; const why = [];
    if (words.some(w => p.type.includes(w)))      { score += 0.45; why.push(`product type matches "${g.category}"`); }
    if (words.some(w => p.title.toLowerCase().includes(w))) { score += 0.30; why.push('title matches category'); }
    if (words.some(w => p.tags.some(t => t.includes(w))))   { score += 0.15; why.push('tag matches category'); }
    if (gColour && p.haystack.includes(gColour)) { score += 0.20; why.push(`colour "${gColour}" matches`); }
    // The detector's own confidence tempers the result, it does not create it.
    score = score * (0.6 + 0.4 * g.confidence);
    return { ...p, score: +Math.min(score, 1).toFixed(3), rationale: why.join('; ') || 'no signal' };
  }).filter(c => c.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, 4);

  const best = scored[0];
  const runnerUp = scored[1];

  let status;
  if (!best)                                     status = 'no_match';
  else if (best.score < LOW)                     status = 'unresolved';
  else if (best.score < HIGH)                    status = 'needs_review';
  else if (runnerUp && best.score - runnerUp.score < 0.12) status = 'ambiguous';
  else if (!best.available)                      status = 'out_of_stock';
  else                                           status = 'high_confidence';

  return { ...g, status, candidates: scored };
});

const blocking = out.filter(g => g.status !== 'high_confidence');

return [{ json: {
  garments: out,
  requires_review: blocking.length > 0,
  review_reasons: blocking.map(g => `${g.id} (${g.category}): ${g.status}`),
  catalogue_size: products.length,
} }];

// Build the metaobject payload. ALWAYS draft: nothing auto-publishes while any
// garment is unresolved, and auto-publish is off by default regardless.
const m = $input.first().json;
const meta = $('Validate upload').first().json;
const fileId = $('Attach image to Shopify').first().json?.data?.fileCreate?.files?.[0]?.id;
if (!fileId) throw new Error('Image did not attach to Shopify Files; refusing to create a half-built outfit.');

// Only high-confidence, in-stock, really-existing products become live hotspots.
const hotspots = m.garments
  .filter(g => g.status === 'high_confidence')
  .map(g => ({
    id: g.id,
    handle: g.candidates[0].handle,
    x: g.anchor.x, y: g.anchor.y,
    ax: g.bbox.x + g.bbox.w / 2,
    ay: g.bbox.y + g.bbox.h / 2,
    label: g.candidates[0].title,
  }));

// Everything uncertain is preserved for the admin to resolve by hand.
const pending = m.garments
  .filter(g => g.status !== 'high_confidence')
  .map(g => ({ id: g.id, category: g.category, colour: g.colour, status: g.status,
               anchor: g.anchor, bbox: g.bbox,
               candidates: g.candidates.map(c => ({ handle: c.handle, title: c.title,
                 score: c.score, available: c.available, rationale: c.rationale })) }));

return [{ json: {
  title: meta.title,
  fileId,
  hotspots: JSON.stringify(hotspots),
  note: pending.length
    ? `${pending.length} garment(s) need review before publishing.`
    : 'All garments matched with high confidence.',
  pending,
  requires_review: m.requires_review,
} }];

