const r = $input.first().json;
const created = r?.data?.metaobjectCreate;
const errs = created?.userErrors || [];
if (errs.length) throw new Error('Shopify refused to save the outfit: ' + JSON.stringify(errs));

const id = created?.metaobject?.id;
const handle = created?.metaobject?.handle;
if (!id) throw new Error('Shopify did not return a metaobject id.');

const build = $('Build outfit record').first().json;

return [{ json: {
  ok: true,
  status: 'DRAFT',
  metaobject_id: id,
  metaobject_handle: handle,
  admin_url: `https://admin.shopify.com/store/qi0zkk-k1/content/entries/shoppable_outfit/${id.split('/').pop()}`,
  live_hotspots: JSON.parse(build.hotspots).length,
  needs_review: build.pending.length,
  pending: build.pending,
  next_step: build.pending.length
    ? 'Open the admin URL, resolve the pending garments, then set the entry to Active.'
    : 'Open the admin URL, check the hotspot positions, then set the entry to Active.',
} }];
